  " Project 전체 (확인된 기간·기준일·환산 정책 유지)": {
    "en": " Entire project (retain confirmed period, reference date and conversion policy)",
    "vi": " Toàn dự án (giữ thời gian, ngày tham chiếu và quy tắc quy đổi đã xác nhận)"
  },
  "Project 전체는 분류·공정·WorkArea·설비·시스템 종류/인스턴스·Task·WBS·Milestone·검색·상태·이동 배정 범위를 제외합니다. 화면 조건과 이동 기록은 유지합니다.": {
    "en": "Whole-project scope excludes classification, process, WorkArea, equipment/system type and instance, Task, WBS, Milestone, search, status and navigation assignment scopes. Screen filters and navigation history remain.",
    "vi": "Phạm vi toàn dự án loại trừ phân loại, công đoạn, WorkArea, loại và thực thể thiết bị/hệ thống, Task, WBS, Milestone, tìm kiếm, trạng thái và phạm vi phân công điều hướng. Giữ nguyên bộ lọc màn hình và lịch sử điều hướng."
  },
