  "Milestone 선택 작업과 전체 Gate 도움말": {
    "en": "Help: Milestone selected tasks and overall gates",
    "vi": "Trợ giúp: Công việc đã chọn và cổng kiểm soát tổng thể của Milestone"
  },
  "작업 검색·상태·기간은 관련 일반 Task와 Assignment 지표에 적용됩니다. 전체 Gate는 전체 소속 작업과 직접 선행 Milestone 기준이며, 선택 범위의 완료나 진척으로 대체하지 않습니다. 겹치는 하위 경로의 소계를 합산하지 않습니다.": {
    "en": "Task search, status, and dates apply to related regular tasks and assignment metrics. Overall gates use all member tasks and direct predecessor Milestones; selected-scope completion or progress does not replace them. Do not add subtotals for overlapping descendant paths.",
    "vi": "Tìm kiếm, trạng thái và khoảng ngày áp dụng cho công việc thông thường liên quan và chỉ số phân công. Cổng kiểm soát tổng thể dựa trên toàn bộ công việc thành viên và Milestone tiền nhiệm trực tiếp; kết quả hoàn thành hoặc tiến độ trong phạm vi đã chọn không thay thế chúng. Không cộng các tổng phụ của nhánh con chồng lấp."
  },
  "아래 전체 상태·관리의 Milestone 검색·표시·공수 조건은 별도 조회입니다. 새 Milestone 추가와 소속·관계 관리는 기존 원본 편집기를 사용합니다.": {
    "en": "The search, display, and effort filters below are separate. Use the existing task editor to add Milestones or manage membership and relationships.",
    "vi": "Các bộ lọc tìm kiếm, hiển thị và công sức bên dưới là độc lập. Dùng trình chỉnh sửa công việc hiện có để thêm Milestone hoặc quản lý thành viên và quan hệ."
  },
